#!/usr/bin/env bash
#
# Claude Code Stop hook: refuse to end a task while the repository's check fails.
# Generated by kition-sdk tools/sync-quality.mjs from templates/quality/claude/quality-gate.sh;
# edit the template there, not this file.
#
# Reads the hook payload from stdin. When stop_hook_active is already true the hook is
# re-entering itself and exits 0 to avoid a loop. KITION_SKIP_QUALITY_HOOK=1 is an emergency,
# session-only bypass; say so in the task's findings.
#
# Exit 2 tells Claude Code the stop was refused; the log tail explains why.

set -uo pipefail

CHECK_COMMAND='pnpm -s typecheck && pnpm -s lint'
REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
LOG_FILE="${TMPDIR:-/tmp}/kition-quality-gate-$(basename "$REPO_DIR").log"

INPUT=""
if [[ ! -t 0 ]]; then
  INPUT="$(cat || true)"
fi

if [[ "$INPUT" == *'"stop_hook_active"'*':'*'true'* ]]; then
  echo "[quality-gate] stop_hook_active=true, skipping to avoid a loop" >&2
  exit 0
fi

if [[ "${KITION_SKIP_QUALITY_HOOK:-0}" == "1" ]]; then
  echo "[quality-gate] KITION_SKIP_QUALITY_HOOK=1, skipping the check" >&2
  exit 0
fi

cd "$REPO_DIR"
echo "[quality-gate] running: $CHECK_COMMAND" >&2

if bash -c "$CHECK_COMMAND" >"$LOG_FILE" 2>&1; then
  echo "[quality-gate] check passed" >&2
  exit 0
fi

{
  echo ""
  echo "[quality-gate] CHECK FAILED: $CHECK_COMMAND. The task is not done."
  echo "[quality-gate] Full log: $LOG_FILE"
  echo "[quality-gate] ---- log tail (last 80 lines) ----"
  tail -n 80 "$LOG_FILE" || true
  echo "[quality-gate] ---- end log tail ----"
  echo "[quality-gate] Fix the failure and retry. Never edit expected results or weaken tests to pass (QUALITY.md)."
} >&2

exit 2
